// /frontend-react/src/App.js (Final Structure for Side Menu Overlay)

import React, { useState } from 'react';
import Dashboard from './components/Dashboard';
import MedicalDashboard from './components/MedicalDashboard';
import AppointmentFlow from './components/AppointmentFlow';
import TransportStatus from './components/TransportStatus';
import MedicineReminder from './components/MedicineReminder';
import SideMenu from './components/SideMenu'; 

// Mock data (remains the same)
const mockAppointmentData = { date: 'Dec 10', time: '10:00 AM', hasTransportBooked: false };

function App() {
    const [currentPage, setCurrentPage] = useState('dashboard'); 
    const [isEasyMode] = useState(true); 
    const [isMenuOpen, setIsMenuOpen] = useState(false); // Controls Menu State

    const handleNotificationClick = () => { setCurrentPage('appointment'); };

    const renderPage = () => {
        // ... (renderPage logic remains the same, passing onMenuClick to all components) ...
        if (currentPage === 'dashboard') {
            return (
                <Dashboard isEasyMode={isEasyMode} goToMedical={() => setCurrentPage('medical-dashboard')} onMenuClick={() => setIsMenuOpen(true)} />
            );
        }
        if (currentPage === 'medical-dashboard') {
             return (
                <MedicalDashboard isEasyMode={isEasyMode} goToPage={setCurrentPage} onMenuClick={() => setIsMenuOpen(true)} />
            );
        }
        // ... (other pages continue to pass the handler) ...
        if (currentPage === 'medicine') {
            return (
                <MedicineReminder isEasyMode={isEasyMode} goToPage={setCurrentPage} onMenuClick={() => setIsMenuOpen(true)} />
            );
        }
        return null; 
    };

    const scrollbarHiddenStyle = {
        'overflowY': 'auto', 
        'msOverflowStyle': 'none', 
        'scrollbarWidth': 'none', 
    };

    return (
        <div style={{ /* ... Outer styles remain the same ... */ }}>
            
            {/* 📱 Phone Casing / Outer Frame */}
            <div 
                style={{
                    // ... Casing styles remain the same ...
                    position: 'relative',
                    overflow: 'hidden', // Essential for transition effect
                }}
            >
                {/* Mock Speaker/Notch (remains the same) */}

                {/* --- 1. Main Content Wrapper (The scrolling screen) --- */}
                <div 
                    style={{
                        // ... Basic screen styles ...
                        height: '100%',
                        width: '100%',
                        borderRadius: '25px', 
                        boxSizing: 'border-box',
                        ...scrollbarHiddenStyle,
                        
                        // KEY FIX: Pushes content left and dims it when menu is open
                        opacity: isMenuOpen ? 0.7 : 1, // Dim effect
                        pointerEvents: isMenuOpen ? 'none' : 'auto', // Disable clicks on content
                        
                        transform: isMenuOpen ? 'scale(0.98) translateX(-50px)' : 'translateX(0)', // Subtle transform effect
                        transition: 'all 0.3s ease-out', // Smooth transition
                    }}
                    className={`App ${isEasyMode ? 'easy-mode-theme' : 'standard-theme'}`}
                >
                    {renderPage()}
                </div>

                {/* --- 2. Side Menu Backdrop (Blocks Clicks on Content) --- */}
                {isMenuOpen && (
                    <div
                        onClick={() => setIsMenuOpen(false)} // Click anywhere to close menu
                        style={{
                            position: 'absolute',
                            top: 0,
                            left: 0,
                            right: 0,
                            bottom: 0,
                            backgroundColor: 'rgba(0, 0, 0, 0.4)', // Dim background
                            zIndex: 90, // Below the SideMenu (100) but above content
                        }}
                    />
                )}

                {/* --- 3. Side Menu Drawer (Slides Over Everything) --- */}
                <SideMenu
                    isEasyMode={isEasyMode}
                    isOpen={isMenuOpen}
                    onClose={() => setIsMenuOpen(false)}
                    goToPage={setCurrentPage}
                />
            </div>
        </div>
    );
}

export default App;
